package thaumcraft.api.casters;
import java.util.*;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.world.entity.LivingEntity;
import net.minecraft.world.phys.*;
/** BETA26 sequential supply engine: mediums stop only for intermediaries; splits execute each branch. */
public final class FocusEngine {
    public static final HashMap<String,Class<? extends IFocusElement>> elements=new HashMap<>();
    private static final Map<String,ResourceLocation> elementIcons=new HashMap<>();private static final Map<String,Integer> elementColor=new HashMap<>();private static final ArrayList<String> damageResistList=new ArrayList<>();
    private FocusEngine(){}
    public static void registerElement(Class<? extends IFocusElement> type,ResourceLocation icon,int color){try{var element=type.getDeclaredConstructor().newInstance();elements.put(element.getKey(),type);elementIcons.put(element.getKey(),icon);elementColor.put(element.getKey(),color);}catch(ReflectiveOperationException e){throw new IllegalArgumentException("Focus element "+type,e);}}
    public static IFocusElement getElement(String key){try{var type=elements.get(key);return type==null?null:type.getDeclaredConstructor().newInstance();}catch(ReflectiveOperationException e){return null;}}
    public static ResourceLocation getElementIcon(String key){return elementIcons.get(key);}public static int getElementColor(String key){return elementColor.getOrDefault(key,0xffffff);}
    public static boolean doesPackageContainElement(FocusPackage p,String key){return p!=null&&p.nodes.stream().anyMatch(n->n.getKey().equals(key));}
    public static void castFocusPackage(LivingEntity caster,FocusPackage focusPackage){castFocusPackage(caster,focusPackage,false);}
    public static void castFocusPackage(LivingEntity caster,FocusPackage focusPackage,boolean nocopy){if(caster.level().isClientSide||focusPackage==null||focusPackage.nodes.isEmpty())return;var copy=nocopy?focusPackage:focusPackage.copy(caster);copy.initialize(caster);copy.setUniqueID(UUID.randomUUID());for(var effect:copy.getFocusEffects())effect.onCast(caster);runFocusPackage(copy,null,null);}
    public static void runFocusPackage(FocusPackage p,Trajectory[] trajectories,HitResult[] targets){run(p,trajectories,targets,0);}
    private static void run(FocusPackage p,Trajectory[] trajectories,HitResult[] targets,int depth){if(p==null||p.nodes.isEmpty()||depth>32||p.world==null||p.world.isClientSide)return;Trajectory[] previousTrajectories=trajectories;HitResult[] previousTargets=targets;synchronized(p.nodes){if(!(p.nodes.get(0) instanceof FocusMediumRoot))p.nodes.add(0,new FocusMediumRoot(trajectories,targets));for(int i=0;i<p.nodes.size();i++){p.setExecutionIndex(i);var element=p.nodes.get(i);if(element instanceof FocusPackage child){child.world=p.world;child.setCasterUUID(p.getCasterUUID());run(child,previousTrajectories,previousTargets,depth+1);break;}if(!(element instanceof FocusNode node))continue;if(i>0&&node.getParent()==null&&p.nodes.get(i-1) instanceof FocusNode parent)node.setParent(parent);if(node.getPackage()==null)node.setPackage(p);p.multiplyPower(node.getPowerMultiplier());if(node instanceof FocusMedium medium){if(previousTrajectories!=null)for(var trajectory:previousTrajectories)medium.execute(trajectory);if(medium.hasIntermediary())break;}else if(node instanceof FocusModSplit split){for(var branch:split.getSplitPackages()){branch.world=p.world;branch.setCasterUUID(p.getCasterUUID());branch.setUniqueID(p.getUniqueID());split.setPackage(branch);branch.multiplyPower(p.getPower());split.execute();run(branch,split.supplyTrajectories(),split.supplyTargets(),depth+1);}break;}else if(node instanceof FocusMod modifier)modifier.execute();else if(node instanceof FocusEffect effect&&previousTargets!=null){for(int num=0;num<previousTargets.length;num++){var target=previousTargets[num];if(target instanceof EntityHitResult entity){String key=entity.getEntity().getId()+String.valueOf(p.getUniqueID());if(damageResistList.contains(key)&&entity.getEntity().invulnerableTime>0)entity.getEntity().invulnerableTime=0;else{if(damageResistList.size()>10)damageResistList.remove(0);damageResistList.add(key);}}var trajectory=previousTrajectories==null||previousTrajectories.length==0?null:previousTrajectories[previousTrajectories.length==previousTargets.length?num:0];effect.execute(target,trajectory,p.getPower(),num);}}previousTrajectories=node.supplyTrajectories();previousTargets=node.supplyTargets();}}}
}
